update public.lessons
set
  format = 'narrated',
  audio_path = '93ca569b-35e6-4e22-8f28-9f94a7306ad1/37c49e32-b60e-4716-b02b-1a90b26f78f1/aula-0.1.mp3',
  content_blocks = '[{"type": "paragraph", "text": "“Quando você ouve Profissão 360, talvez a primeira coisa que venha à sua cabeça seja uma câmera 360°. E sim, você vai aprender a trabalhar com esse tipo de equipamento. Mas ser um Profissional 360° vai muito além disso.”"}, {"type": "paragraph", "text": "O 360°, aqui dentro, representa a forma como a gente olha para o negócio do cliente."}, {"type": "paragraph", "text": "A gente não olha somente se o cara tem Instagram, se tá no Google ou se tem um site."}, {"type": "paragraph", "text": "A gente olha para toda a presença digital da empresa e tenta entender como essas partes estão trabalhando juntas."}, {"type": "paragraph", "text": "Ou, na maioria dos casos, como elas não estão trabalhando juntas."}, {"type": "paragraph", "text": "Porque uma empresa pode ter Google e mesmo assim ninguém conseguir encontrar ela."}, {"type": "paragraph", "text": "Ela pode ter um site bonito, mas o site não explica direito o que ela faz."}, {"type": "paragraph", "text": "E também pode acontecer de a empresa receber vários contatos, mas perder essas oportunidades porque não tem organização, acompanhamento ou um processo comercial definido."}, {"type": "paragraph", "text": "Então galera ao final do curso, você vão adquirir várias habilidades que vão te ensinar a se adaptar ao ambiente e ter a visão ampla do todo."}, {"type": "paragraph", "text": "E conseguir olhar para o negócio, identificar onde está o problema e conectar diferentes soluções para resolver esse problema."}, {"type": "paragraph", "text": "Às vezes, o cliente precisa começar pelo Google Meu Negócio."}, {"type": "paragraph", "text": "Em outro caso, ele precisa de um site pra linkar no perfil do Google dele ou no link da bio do Instagram."}, {"type": "paragraph", "text": "Talvez precise de um tour virtual para mostrar melhor o espaço."}, {"type": "paragraph", "text": "Pode precisar de uma área de membros para a equipe ou os clientes, talvez um chatbot pra responder as dúvidas dos clientes na hora, ou de uma estrutura para acompanhar os clientes que estão chegando."}, {"type": "paragraph", "text": "Enfim, o trabalho do Profissional 360° não é sair oferecendo tudo para todo mundo."}, {"type": "paragraph", "text": "O seu trabalho é entender qual é o problema e qual é a próxima solução que realmente faz sentido para aquele negócio."}, {"type": "paragraph", "text": "E eu quero deixar uma coisa clara desde o começo: você não precisa ser o maior especialista do mundo em todas as áreas para começar."}, {"type": "paragraph", "text": "Mas você precisa saber entregar aquilo que está vendendo."}, {"type": "paragraph", "text": "E, principalmente, precisa entender como essa entrega se conecta com o restante do negócio."}, {"type": "paragraph", "text": "Essa profissão também representa muito a minha própria trajetória."}, {"type": "paragraph", "text": "Eu não comecei com uma agência estruturada, não tinha equipe, não tinha plano de negócios."}, {"type": "paragraph", "text": "Eu comecei como Local Guide usando só meu celular fazendo avaliações no Google Maps."}, {"type": "paragraph", "text": "Eu sempre gostei de viajar, registrar lugares, de tecnologia e de ajudar as pessoas."}, {"type": "paragraph", "text": "Sempre tive a veia de empreendedor e na pandemia fechei minha empresa, eu tinha uma assistência técnica tá e desfiz minha equipe viajei, fui morar na praia, foi na época da pandemia isso."}, {"type": "paragraph", "text": "Com o tempo, comecei a trocar ideia com viajantes, turistas, e perceber como as pessoas viajam e descobrem lugares, entendi o outro lado, como cliente visitando um comércio, e entendendo o impacto que uma boa presença na internet poderia gerar na receita de uma empresa."}, {"type": "paragraph", "text": "Depois virei videomaker com meu próprio celular e entregar conteúdos de valor para meus clientes e fazer conexões com festas e eventos e eu comecei a criar coisas cada vez mais ousadas e tudo aos poucos foi se conectando, e começaram a surgir os primeiros projetos."}, {"type": "paragraph", "text": "Com uma câmera 360° e um drone, eu conseguia transformar um espaço físico em uma experiência digital: começar com uma visão aérea da região e levar a pessoa para dentro do local, navegando entre imagens aéreas e terrestres como se estivesse ali."}, {"type": "paragraph", "text": "Só que, conforme eu atendia os clientes, eu percebia uma coisa: entregar as imagens não resolvia tudo."}, {"type": "paragraph", "text": "O cliente também precisava ser encontrado."}, {"type": "paragraph", "text": "Precisava apresentar melhor os serviços ou o seu espaço."}, {"type": "paragraph", "text": "Precisava ter um site com o SEO bom pro Google referenciar ele."}, {"type": "paragraph", "text": "Precisava receber os contatos."}, {"type": "paragraph", "text": "Precisava organizar os projetos e os clientes."}, {"type": "paragraph", "text": "E foi por isso que eu fui avançando para outras áreas."}, {"type": "paragraph", "text": "Eu fui aprendendo porque cada projeto mostrava um problema novo que precisava ser resolvido."}, {"type": "paragraph", "text": "Hoje, depois de milhões de visualizações no Google Maps e dezenas de projetos entregues entre Google, sites e tours, eu consigo olhar para trás e enxergar esse caminho como uma profissão."}, {"type": "paragraph", "text": "E é esse caminho que eu organizei dentro deste curso."}, {"type": "paragraph", "text": "Na Real Vision, a gente chama isso de Sistema PDI: Presença Digital Integrada."}, {"type": "paragraph", "text": "O Sistema PDI é uma metodologia para organizar os diferentes elementos da presença digital de uma empresa."}, {"type": "paragraph", "text": "Ele serve para colocar todas as plataformas do negócio conectadas funcionando como peças complementares de uma mesma engrenagem."}, {"type": "paragraph", "text": "E como isso funciona aplicado ao negócio?"}, {"type": "paragraph", "text": "Primeiro, a gente identifica onde tá gargalo, na visibilidade, confiança ou conversão."}, {"type": "paragraph", "text": "Depois, a gente escolhe as soluções necessárias para corrigir esse problema."}, {"type": "paragraph", "text": "Nem todo cliente precisa contratar tudo de uma vez, a grande maioria dos clientes a melhor ideia é desenvolver tudo por etapas."}, {"type": "paragraph", "text": "Mas você, como profissional, precisa enxergar o quadro inteiro para conseguir recomendar o próximo passo correto."}, {"type": "paragraph", "text": "E existe uma parte fundamental dessa profissão: a inteligência artificial."}, {"type": "paragraph", "text": "Aqui, a inteligência artificial não vai aparecer apenas como uma ferramenta para escrever texto ou gerar uma imagem."}, {"type": "paragraph", "text": "Ela vai ser a mágica por trás integrada em vários processos da empresa."}, {"type": "paragraph", "text": "Você vai aprender a usar inteligência artificial para pesquisar, planejar, criar, documentar, organizar projetos e apoiar a gestão dos seus clientes."}, {"type": "paragraph", "text": "Nos módulos mais avançados, você também vai conhecer o Sócio Digital."}, {"type": "paragraph", "text": "O Sócio Digital é um conjunto de etapas que eu desenvolvi e aprimorei onde eu te ensino como criar e configurar uma pasta dentro do seu computador e trabalhar dentro dela, ele vira o sistema operacional da empresa, o cérebro centralizado onde toda a verdade institucional, onde sua empresa vive, e nele eu instalo um sistema de multi agentes que trabalha pra você com o contexto da sua empresa."}, {"type": "paragraph", "text": "Na prática, a ideia é fazer com que as informações importantes do seu negócio não existam apenas dentro da sua cabeça."}, {"type": "paragraph", "text": "Os seus processos, os seus clientes, os seus padrões e os seus projetos passam a ser mapeados, documentados e organizados."}, {"type": "paragraph", "text": "Assim, a inteligência artificial consegue trabalhar com a pasta da sua empresa com tudo dentro e ajudar com informações reais e precisas do contexto da sua empresa."}, {"type": "paragraph", "text": "Mas isso não significa entregar a empresa para um chatbot e esperar que ele faça tudo sozinho."}, {"type": "paragraph", "text": "A responsabilidade continua e sempre será sua."}, {"type": "paragraph", "text": "A IA ajuda a acelerar e organizar o trabalho, mas você continua tomando as decisões e garantindo a qualidade da entrega."}, {"type": "paragraph", "text": "Ah e um conselho a quem não gosta de ler, aprenda a gostar de ler, isso foi uma barreira que eu tive que aprender a quebrar dentro de mim mesmo também no início, a IA vai criar coisas incríveis pra você mas todas elas você vai precisar ler pra poder entender exatamente o que está sendo feito, e eu leio muito cara, todos os dias."}, {"type": "paragraph", "text": "Você também vai ter acesso a um CRM e dashboard para organizar os seus clientes, os serviços contratados, as tarefas e os próximos passos de cada projeto."}, {"type": "paragraph", "text": "Isso permite que uma pessoa só consiga operar várias frentes de uma empresa sozinho ou de forma muito mais organizada."}, {"type": "paragraph", "text": "Isso é um modelo de operação enxuta, com tecnologia aplicada a processos e impulsionada pela inteligência artificial, isso ajuda você a atender mais clientes sem depender de uma estrutura pesada."}, {"type": "paragraph", "text": "E este curso não serve apenas para quem quer vender esses serviços."}, {"type": "paragraph", "text": "Ele também serve para você que já tem um negócio e quer aplicar esses conhecimentos dentro da sua própria empresa."}, {"type": "paragraph", "text": "Ou talvez você seja dono de uma empresa e queira treinar um funcionário para cuidar do Google, do site, da presença digital ou de parte desses processos."}, {"type": "paragraph", "text": "O conhecimento é o mesmo."}, {"type": "paragraph", "text": "O que muda é onde você vai aplicar."}, {"type": "paragraph", "text": "Você pode utilizar isso como uma profissão e prestar serviços para outras empresas."}, {"type": "paragraph", "text": "Pode aplicar dentro do seu próprio negócio."}, {"type": "paragraph", "text": "Ou pode usar esse conhecimento dentro da empresa onde você trabalha."}, {"type": "paragraph", "text": "Essa é a profissão do futuro. A internet e o meio digital hoje não são apenas canais de vendas ou plataformas de mídia... **são a própria extensão da realidade.**"}, {"type": "paragraph", "text": "E é aqui que a chave precisa virar na sua cabeça."}, {"type": "paragraph", "text": "Com quantos anos você descobriu que as redes sociais são, na verdade, o novo **reino astral**?"}, {"type": "paragraph", "text": "Pense comigo. O que é o reino astral se não um campo de manifestação de múltiplas realidades que distorcem o tempo? Onde passado, presente e futuro se entrelaçam e criam uma malha invisível capaz de se manifestar diretamente na matéria?"}, {"type": "paragraph", "text": "Pois saiba que absolutamente tudo o que você constrói aqui se manifesta na sua vida material."}, {"type": "paragraph", "text": "Você nunca achou isso profundamente estranho? Neste exato momento, você está vendo um vídeo de alguém falando de um lugar que você nem sabe de onde é. E eu já nem estou mais aí fisicamente, porque esse vídeo ficou no meu passado — mas para você, ele está acontecendo agora, no seu presente."}, {"type": "paragraph", "text": "Esse o smartphone na sua mão ou o seu notebook na sua mesa são as ferramentas dos criadores dessa realidade."}, {"type": "paragraph", "text": "Mas a maioria dos negócios comete o erro fatal de construir toda a sua vida dentro do castelo dos outros. Acreditam que ter uma rede social é ter uma empresa digital, quando na verdade estão apenas alimentando a plataforma alheia."}, {"type": "paragraph", "text": "Enquanto a grande massa entra nas redes todos os dias para ser hipnotizada — servindo apenas como combustível para a magia e o algoritmo dos outros —, o **Profissional 360°** aprende a dominar essa estrutura por completo. Você usa o Instagram para atrair, mas traz a pessoa para o **seu próprio terreno**, para a sua própria experiência, onde você retém o controle."}, {"type": "paragraph", "text": "Com a Inteligência Artificial do nosso lado, resolver qualquer problema se resume a duas coisas: saber qual ferramenta usar e como usar. E o segredo de tudo isso é saber fazer a pergunta certa. Quando você aprende a perguntar com precisão, a solução vem de forma simples."}, {"type": "paragraph", "text": "É assim que você deixa de ser um espectador no feed dos outros para virar quem realmente orquestra o jogo."}, {"type": "paragraph", "text": "A partir de agora, você não vai apenas aprender a mexer no Google, criar sites, fazer tours ou captar clientes. Você vai aprender a fazer as perguntas certas e usar a ferramenta com sabedoria, intencionalidade e maestria."}, {"type": "paragraph", "text": "Seja bem-vindo à **Profissão 360°**. Abra a sua mente... e nos vemos na próxima aula."}]'::jsonb,
  sync_map = '{"fragments": [{"text": "“Quando você ouve Profissão 360, talvez a primeira coisa que venha à sua cabeça seja uma câmera 360°.", "begin": 0.0, "end": 9.44}, {"text": "E sim, você vai aprender a trabalhar com esse tipo de equipamento.", "begin": 9.44, "end": 11.88}, {"text": "Mas ser um Profissional 360° vai muito além disso.”", "begin": 11.88, "end": 16.76}, {"text": "O 360°, aqui dentro, representa a forma como a gente olha para o negócio do cliente.", "begin": 16.76, "end": 21.32}, {"text": "A gente não olha somente se o cara tem Instagram, se tá no Google ou se tem um site.", "begin": 21.32, "end": 25.56}, {"text": "A gente olha para toda a presença digital da empresa e tenta entender como essas partes estão trabalhando juntas.", "begin": 25.56, "end": 32.16}, {"text": "Ou, na maioria dos casos, como elas não estão trabalhando juntas.", "begin": 32.16, "end": 36.48}, {"text": "Porque uma empresa pode ter Google e mesmo assim ninguém conseguir encontrar ela.", "begin": 36.48, "end": 40.52}, {"text": "Ela pode ter um site bonito, mas o site não explica direito o que ela faz.", "begin": 40.52, "end": 44.64}, {"text": "E também pode acontecer de a empresa receber vários contatos, mas perder essas oportunidades porque não tem organização, acompanhamento ou um processo comercial definido.", "begin": 44.64, "end": 53.68}, {"text": "Então galera ao final do curso, você vão adquirir várias habilidades que vão te ensinar a se adaptar ao ambiente e ter a visão ampla do todo.", "begin": 53.68, "end": 64.6}, {"text": "E conseguir olhar para o negócio, identificar onde está o problema e conectar diferentes soluções para resolver esse problema.", "begin": 64.6, "end": 73.08}, {"text": "Às vezes, o cliente precisa começar pelo Google Meu Negócio.", "begin": 73.08, "end": 76.28}, {"text": "Em outro caso, ele precisa de um site pra linkar no perfil do Google dele ou no link da bio do Instagram.", "begin": 76.28, "end": 82.56}, {"text": "Talvez precise de um tour virt